        if(p.has("input_pcm_file") || p.has("output_pcm_file"))throw new IllegalStateException("D181 catalog guard must not declare rendered or stream input PCM");
        for(var entry:p.getAsJsonObject("evidence_sha256").entrySet())if(!sha(bytes(root.resolve(entry.getKey()))).equals(entry.getValue().getAsString()))throw new IllegalStateException("D181 catalog guard evidence changed: "+entry.getKey());
