    private static JsonObject caseRow(String name) {requireClient(Minecraft.getInstance());JsonObject r=new JsonObject();r.addProperty("name",name);r.addProperty("order",++order);r.addProperty("started_utc",Instant.now().toString());r.addProperty("actual_client_thread",true);r.addProperty("thread",Thread.currentThread().getName());r.addProperty("before_catalog_identity",System.identityHashCode(CalibratedAssetResources.snapshot()));r.addProperty("before_catalog_asset_count",CalibratedAssetResources.snapshot().assets().size());r.add("before_publication",publicationState(publicationSnapshot()));return r;}
    private static void finish(JsonArray cases,JsonObject r){r.addProperty("after_catalog_identity",System.identityHashCode(CalibratedAssetResources.snapshot()));r.addProperty("after_catalog_asset_count",CalibratedAssetResources.snapshot().assets().size());r.add("after_publication",publicationState(publicationSnapshot()));r.addProperty("end_order",++order);r.addProperty("finished_utc",Instant.now().toString());cases.add(r);}
