    private static void applySuccess(Minecraft client,CalibratedAssetResources loader,CalibratedAssetResources.Catalog next,JsonObject r){requireClient(client);r.add("before_publication",publicationState(publicationSnapshot()));r.addProperty("production_method","CalibratedAssetResources.apply");r.addProperty("next_catalog_identity",System.identityHashCode(next));CompletableFuture<Void> future=loader.apply(next,client.getResourceManager(),Runnable::run);r.addProperty("future_done_before_join",future.isDone());future.join();r.add("after_publication",publicationState(publicationSnapshot()));r.addProperty("future_joined",true);r.addProperty("future_completed_exceptionally",future.isCompletedExceptionally());r.addProperty("published_exact_requested_catalog",CalibratedAssetResources.snapshot()==next);if(CalibratedAssetResources.snapshot()!=next || future.isCompletedExceptionally())throw new IllegalStateException("D181 successful actual apply did not publish requested catalog");}
    private static void applyReject(Minecraft client,CalibratedAssetResources loader,CalibratedAssetResources.Catalog next,CalibratedAssetResources.Catalog previous,JsonObject r){requireClient(client);if(CalibratedAssetResources.snapshot()!=previous)throw new IllegalStateException("D181 rejection started from wrong previous object");var beforePublication=publicationSnapshot();r.add("before_publication",publicationState(beforePublication));r.addProperty("production_method","CalibratedAssetResources.apply");r.addProperty("before_catalog_identity",System.identityHashCode(previous));r.addProperty("next_catalog_identity",System.identityHashCode(next));CompletableFuture<Void> future=loader.apply(next,client.getResourceManager(),Runnable::run);r.addProperty("future_done_before_join",future.isDone());joinRejected(future,r);var afterPublication=publicationSnapshot();r.add("after_publication",publicationState(afterPublication));r.addProperty("after_catalog_identity",System.identityHashCode(CalibratedAssetResources.snapshot()));r.addProperty("retained_exact_previous_catalog",CalibratedAssetResources.snapshot()==previous);r.addProperty("retained_exact_previous_publication_snapshot",beforePublication==afterPublication);if(CalibratedAssetResources.snapshot()!=previous || beforePublication!=afterPublication)throw new IllegalStateException("D181 exceptional actual apply changed previous publication snapshot");}
