        r.addProperty("malformed_profile_resource",id.toString());r.addProperty("malformed_payload_utf8","{");r.addProperty("malformed_payload_sha256",sha(malformed));r.addProperty("malformed_resource_manager_identity",System.identityHashCode(broken));r.addProperty("production_load_method","CalibratedAssetResources.load");var beforeLoad=publicationSnapshot();r.add("before_load_publication",publicationState(beforeLoad));CompletableFuture<CalibratedAssetResources.Catalog> future=loader.load(broken,Runnable::run);CalibratedAssetResources.Catalog retained=future.join();var afterLoad=publicationSnapshot();r.add("after_load_publication",publicationState(afterLoad));r.addProperty("retained_exact_publication_after_load",beforeLoad==afterLoad);r.addProperty("load_future_joined",true);r.addProperty("load_future_completed_exceptionally",future.isCompletedExceptionally());r.addProperty("returned_catalog_identity",System.identityHashCode(retained));r.addProperty("resource_open_calls",opens.get());r.add("resource_calls",calls);if(retained!=previous || CalibratedAssetResources.snapshot()!=previous || opens.get()!=1 || beforeLoad!=afterLoad)throw new IllegalStateException("actual malformed JSON load did not retain exact previous publication after opening the resource");applySuccess(client,loader,retained,r);r.addProperty("retained_exact_previous_catalog",CalibratedAssetResources.snapshot()==previous);finish(cases,r);
