        var beforeEnqueue=publicationSnapshot();r.addProperty("production_method","CalibratedAssetResources.apply");r.addProperty("next_catalog_identity",System.identityHashCode(otherScale));CompletableFuture<Void> future=loader.apply(otherScale,client.getResourceManager(),deferred);var afterEnqueue=publicationSnapshot();r.add("publication_after_enqueue",publicationState(afterEnqueue));r.addProperty("retained_exact_previous_publication_after_enqueue",beforeEnqueue==afterEnqueue);r.addProperty("queued_task_count",tasks.size());r.addProperty("future_done_before_execution",future.isDone());r.addProperty("catalog_identity_after_enqueue",System.identityHashCode(CalibratedAssetResources.snapshot()));r.addProperty("retained_exact_previous_after_enqueue",CalibratedAssetResources.snapshot()==previous);if(tasks.size()!=1 || future.isDone() || CalibratedAssetResources.snapshot()!=previous || beforeEnqueue!=afterEnqueue)throw new IllegalStateException("actual apply validated/published before deferred executor task");
