        var beforeExecution=publicationSnapshot();r.add("publication_before_deferred_execution",publicationState(beforeExecution));r.addProperty("deferred_execution_actual_client_thread",client.isSameThread());r.addProperty("deferred_execution_thread",Thread.currentThread().getName());Runnable task=tasks.removeFirst();task.run();r.addProperty("queued_tasks_after_execution",tasks.size());joinRejected(future,r);var afterExecution=publicationSnapshot();r.add("publication_after_deferred_execution",publicationState(afterExecution));r.addProperty("retained_exact_newest_publication_snapshot",beforeExecution==afterExecution);r.addProperty("retained_exact_newest_catalog",CalibratedAssetResources.snapshot()==newest);if(CalibratedAssetResources.snapshot()!=newest || beforeExecution!=afterExecution)throw new IllegalStateException("deferred conflicting apply did not retain exact newest publication snapshot");finish(cases,r);
